const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=Gear.numeric;
const fmt=(n,p=2)=>n===null||n===undefined?'—':Number(n).toLocaleString('fr-FR',{maximumFractionDigits:p}),grams=n=>n==null?'Inconnu':n>=1000?fmt(n/1000,3)+' kg':fmt(n,2)+' g';
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},when=s=>s&&Number.isFinite(Date.parse(s))?new Date(s).toLocaleString('fr-FR',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const paths={home:'m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9',inventory:'M7 5h10a3 3 0 0 1 3 3v13H4V8a3 3 0 0 1 3-3m2 0V3h6v2M8 10h8M8 14h8M8 18h4',packs:'M7 7V5a5 5 0 0 1 10 0v2M6 7h12v15H6V7m0 4H3v8h3m12-8h3v8h-3M9 13h6v6H9z',prep:'M9 4V2h6v2M5 4h14v18H5V4m3 5 1 1 2-2m2 2h3M8 15l1 1 2-2m2 2h3',wear:'m4 4 5 1 2 4 4 2 4-2 2 4-4 5-4 1-4-4-4-2-1-9m6 14-3 4m10-8 4 5',stats:'M4 20V10h3v10m4 0V4h3v16m4 0v-7h3v7M2 21h20',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-2-6h4l1 3 3 2 3-1 2 4-2 2v3l2 2-2 4-3-1-3 2-1 2h-4l-1-2-3-2-3 1-2-4 2-2v-3L1 10l2-4 3 1 3-2 1-3',data:'M4 5c0-4 16-4 16 0s-16 4-16 0v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0',wishes:'M20 5c-3-3-6 0-8 2-2-2-5-5-8-2-4 4 1 9 8 15 7-6 12-11 8-15',more:'M5 12h.01M12 12h.01M19 12h.01',filter:'M3 5h18l-7 8v7l-4-2v-5L3 5',arrow:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',check:'m5 12 4 4L20 5',close:'m5 5 14 14M5 19 19 5',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2m-1 5a6 6 0 1 1-12 0 6 6 0 0 1 12 0',plus:'M12 4v16M4 12h16',edit:'m4 16 12-12 4 4L8 20H4v-4m10-10 4 4',copy:'M8 8h13v13H8V8M4 16H2V2h14v2',weight:'M5 6h14l3 15H2L5 6m4 0a3 3 0 1 1 6 0m-3-1v4',clock:'M12 8v5l3 2m7-3a10 10 0 1 1-20 0 10 10 0 0 1 20 0',mountain:'m2 20 7-13 5 9 3-6 5 10H2m5-9 2 2 2-2',download:'M12 2v13m-5-5 5 5 5-5M3 16v5h18v-5',up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6',photo:'M3 6h5l2-3h4l2 3h5v15H3V6m13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',pin:'M12 22c-8-10-9-13-6-17 3-4 9-4 12 0 3 4 2 7-6 17m3-14a3 3 0 1 1-6 0 3 3 0 0 1 6 0',alert:'m12 2 10 19H2L12 2m0 6v6m0 3h.01'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.inventory}"/></svg>`;
const labels={home:'Accueil',inventory:'Inventaire',packs:'Configurations',prep:'Préparation',wear:'Usure & état',wishes:'Souhaits & remplacements',stats:'Statistiques',data:'Données & sauvegardes',settings:'Paramètres',item:'Fiche équipement',pack:'Configuration'};
const parentView=()=>view==='item'?'inventory':view==='pack'?'packs':view;
let state=Gear.fresh(),loaded=false,blocked=null,busy=false,externalPending=false,view='home',itemId=null,packId=null,listId=null,detailTab='details',packTab='content',inventoryMode='categories',filter={q:'',category:'',location:'',condition:'',kind:'',tags:[],tagMode:'all',unknown:false,includeHidden:false},customizing=false,compareIds=['',''],simulation=null,photoDraft=[],editingItemId=null,acquiringWishId=null,pendingRestore=null,pendingCSV=null,swWaiting=null,installPrompt=null,wearFilter='all';
const channel='BroadcastChannel'in globalThis?new BroadcastChannel('mygear-equipment-studio-v2'):null;
function photoKey(s=''){s=Gear.norm(s);return /sac|portage|backpack/.test(s)?'pack':/couchage|matelas|tapis|oreiller/.test(s)?'sleep':/abri|tente|bivouac|tarp/.test(s)?'shelter':/cuisine|eau|gaz|repas|popote/.test(s)?'cook':/vetement|veste|pantalon|chaussure/.test(s)?'clothes':/navigation|gps|electron|telephone/.test(s)?'electronic':/securite|soin|sante|medic/.test(s)?'safety':'misc'}
const photo=i=>i?.photo||'assets/'+photoKey((i?.category||'')+' '+(i?.name||''))+'.webp',catPhoto=name=>'assets/'+photoKey(name)+'.webp';
const activePack=()=>state.packs.find(p=>p.id===state.settings.activePackId),ownEntries=()=>state.items.map(i=>({itemId:i.id,qty:i.qty}));
const stockTotals=()=>Gear.totals(state,ownEntries()),unknownLabel=t=>t.unknown?`${t.unknown} unité(s) sans poids · total partiel`:`${t.known}/${t.units} unités avec poids`;
function mass(t,key='total'){const unknown=key==='bag'?t.unknownByKind.base+t.unknownByKind.consumable:key==='total'?t.unknown:t.unknownByKind[key];if(unknown&&t[key]===0)return 'Inconnu';return (unknown?'≥ ':'')+grams(t[key])}
const alerts=()=>state.items.filter(i=>i.wear!==null&&i.wear>=i.wearLimit||['À remplacer','Hors service'].includes(i.condition));
function toast(message){$('toast').textContent=message;$('toast').classList.add('toast-visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('toast-visible'),4000);if($('sheet').open){let el=$('sheet-status');if(!el){el=document.createElement('p');el.id='sheet-status';el.className='notice';el.setAttribute('role','status');$('sheetBody').append(el)}el.textContent=message}}
async function commit(fn,message='Enregistré sur cet appareil',{restore=false,replace=null}={}){if(busy)return false;if(blocked&&!restore){toast('Le stockage existant est protégé. Restaure une sauvegarde valide.');return false}busy=true;document.body.setAttribute('aria-busy','true');try{const draft=replace?Gear.copy(replace):Gear.copy(state);fn(draft);Gear.validate(draft);const saved=await GearStore.write(draft,{expectedRevision:state.revision,restore,forceRecovery:restore&&Boolean(blocked)});state=saved;blocked=null;loaded=true;channel?.postMessage({revision:state.revision});render();if(message)toast(message);return true}catch(e){toast('Modification non enregistrée : '+e.message);return false}finally{busy=false;document.body.setAttribute('aria-busy','false')}}
function applyTheme(){const light=state.settings.theme==='light'||state.settings.theme==='auto'&&matchMedia('(prefers-color-scheme: light)').matches;document.body.classList.toggle('light',light);document.querySelector('meta[name=theme-color]').content=light?'#f5f0e8':'#172016'}
matchMedia('(prefers-color-scheme: light)').addEventListener('change',applyTheme);
function shell(){applyTheme();const current=parentView(),nav=['home','inventory','packs','prep','wear','wishes','stats','data','settings'];$('rail').innerHTML=`<div class="brand"><img class="logo" src="assets/icon.svg" alt=""><div><b>MY GEAR</b><small>Equipment Studio</small></div></div><nav aria-label="Navigation latérale">${nav.map(k=>`<button data-nav="${k}" class="${k===current?'active':''}" ${k===current?'aria-current="page"':''}>${icon(k)}${labels[k]}</button>`).join('')}</nav><div class="rail-foot"><span class="eyebrow">PRÊT POUR LA SUITE</span><p class="muted">Chaque objet.<br>La bonne place.</p><small>Equipment Studio 2.0<br>Inventaire local & hors ligne</small></div>`;
 $('topbar').innerHTML=`<div class="brand mobile-brand"><img class="logo" src="assets/icon.svg" alt=""><div><b>MY GEAR</b><small>Equipment Studio</small></div></div><div class="breadcrumb"><span class="eyebrow">EQUIPMENT STUDIO</span><span class="muted">/</span><span class="view-label">${labels[view]}</span></div><div class="top-actions">${swWaiting?'<button data-action="update">Mise à jour prête</button>':''}<span class="view-label ${navigator.onLine?'':'offline'}">${navigator.onLine?'Données locales':'Hors ligne'}</span><button data-action="theme" aria-label="Changer le thème">${icon('sun')}</button><button data-action="new-item" class="primary" aria-label="Ajouter un équipement">${icon('plus')}</button></div>`;
 $('bottom').innerHTML=['home','inventory','packs','prep','more'].map(k=>`<button ${k==='more'?'data-action="more"':`data-nav="${k}"`} class="${k===current||k==='more'&&!['home','inventory','packs','prep'].includes(current)?'active':''}" ${k===current?'aria-current="page"':''}>${icon(k)}${({home:'Accueil',inventory:'Inventaire',packs:'Configs',prep:'Prépa',more:'Plus'})[k]}</button>`).join('')}
function heading(title,subtitle='',action=''){return `<div class="page-heading"><div><span class="eyebrow">MY GEAR · EQUIPMENT STUDIO</span><h1>${title}</h1>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div>${action}</div>`}
const stat=(value,label,key='inventory')=>`<div class="stat">${icon(key)}<b>${value}</b><small>${label}</small></div>`;
function parseRoute(){const h=location.hash.slice(1).split('/');view=labels[h[0]]?h[0]:'home';if(view==='item')itemId=decodeURIComponent(h.slice(1).join('/'));if(view==='pack')packId=decodeURIComponent(h.slice(1).join('/'));}
function navigate(key,id=null){if(!labels[key])return;view=key;if(key==='item')itemId=id;if(key==='pack'){packId=id;packTab='content'}if(key!=='pack')simulation=null;const route=key+(id?'/'+encodeURIComponent(id):'');history.replaceState(null,'','#'+route);closeSheet();render();window.scrollTo({top:0});$('main').focus({preventScroll:true})}
function render(){const expanded=new Map([...document.querySelectorAll('[data-prep-group]')].map(e=>[e.dataset.prepGroup,e.open]));shell();document.title='MY GEAR · '+labels[view];if(!loaded){$('main').innerHTML=heading('Equipment Studio','Ouverture de ton inventaire…');return}if(blocked){$('main').innerHTML=heading('Données protégées','L’état existant n’a pas été remplacé.')+`<section class="card"><div class="notice">${esc(blocked)}</div><button data-action="raw-export">Exporter les données brutes de récupération</button><label class="section-gap">Restaurer une sauvegarde valide<input id="restore-input" type="file" accept=".json,application/json"></label><div id="restore-preview"></div></section>`;return}const page={home,inventory,packs,prep,wear,wishes,stats,data:dataPage,settings,item:itemPage,pack:packPage};$('main').innerHTML=(state.testFixture?'<div class="notice">JEU DE TEST ANONYME · valeurs fictives de validation</div>':'')+page[view]();document.querySelectorAll('[data-prep-group]').forEach(e=>{if(expanded.has(e.dataset.prepGroup))e.open=expanded.get(e.dataset.prepGroup)});if(view==='data')checkOffline()}
function empty(message,button='',asset='pack'){return `<div class="empty"><img class="empty-illustration" src="assets/${asset}.webp" alt=""><p>${message}</p>${button}</div>`}
function home(){const p=activePack(),t=p?Gear.totals(state,p.entries):null,w=alerts(),l=state.lists[0],r=l?Gear.ready(state,l):null,stock=stockTotals();const modules={
 active:`<div class="between"><h2>Ma configuration active</h2>${p?`<button data-action="choose-active" class="ghost" aria-label="Choisir une configuration">${icon('edit')}</button>`:''}</div>${p?`<div class="active-pack"><img src="${packPhoto(p)}" alt="Visuel de sac"><div class="pack-info"><h3>${esc(p.name)}</h3><small>${esc(p.activity||'Configuration personnelle')}${p.days?' · '+fmt(p.days,0)+' jour(s)':''}</small><div class="weight">${mass(t,'bag')}</div><small>Poids du sac au départ${t.unknown?' · incomplet':''}</small><div class="badges section-gap"><span class="badge">Base ${mass(t,'base')}</span><span class="badge">Porté ${mass(t,'worn')}</span></div></div><button class="ghost" data-pack="${esc(p.id)}" aria-label="Ouvrir ${esc(p.name)}">${icon('arrow')}</button></div><p class="inline-note">${unknownLabel(t)}</p>`:empty('Choisis une configuration pour retrouver son poids et sa préparation.',`<button data-action="choose-active" class="primary section-gap">Choisir une configuration</button>`)}`,
 quick:`<div class="between"><h2>Mon équipement</h2>${icon('packs')}</div><div class="quick-grid"><button data-nav="inventory">${icon('inventory')}Inventaire</button><button data-nav="packs">${icon('packs')}Configs</button><button data-nav="prep">${icon('prep')}Préparation</button></div><p class="muted section-gap">Ajoute tes objets, compose tes sacs et prépare chaque départ.</p>`,
 readiness:`<div class="between"><h2>Préparation</h2><button data-nav="prep" class="ghost" aria-label="Ouvrir la préparation">${icon('arrow')}</button></div>${l?`<h3>${esc(l.name)}</h3><div class="progress-label section-gap"><span>${r.prepared}/${r.required} unités prêtes</span><b>${r.percent} %</b></div><progress max="100" value="${r.percent}" aria-label="Progression de préparation"></progress><div class="metric-line"><span>Unités manquantes</span><b>${r.missing}</b></div><p class="muted">Les quantités prêtes tiennent compte du stock disponible.</p>`:empty('Aucune liste créée pour le moment.',`<button data-action="new-list" class="ghost section-gap">Créer une liste</button>`,'misc')}`,
 wear:`<div class="between"><h2>Usure & état</h2><span class="badge ${w.length?'red':''}">${w.length} alerte(s)</span></div>${w.length?w.slice(0,4).map(itemRow).join(''):'<div class="notice">Aucun seuil atteint dans les données renseignées. Les usures inconnues restent à évaluer.</div>'}<button data-nav="wear" class="ghost section-gap">Voir le suivi des articles ${icon('arrow')}</button>`,
 stock:`<div class="between"><h2>Le studio en chiffres</h2><button data-nav="stats" class="ghost">Statistiques ${icon('arrow')}</button></div><div class="number-grid">${stat(state.items.reduce((n,i)=>n+i.qty,0),'Unités possédées','inventory')}${stat(mass(stock),'Masse connue du stock · '+unknownLabel(stock),'weight')}${stat(state.wishes.length,'Souhaits & remplacements','wishes')}${stat(Gear.locations(state).length,'Emplacements et niveaux','pin')}</div><p class="muted section-gap">Masse du stock, distincte du poids d’une configuration réellement préparée.</p>`};
 return `<div class="between" style="margin-bottom:12px"><span class="eyebrow">TON ÉQUIPEMENT, AU BON ENDROIT</span><button data-action="customize" class="ghost">${customizing?'Terminer':'Personnaliser'}</button></div><div class="hero gear-hero"><div><span class="eyebrow">MY GEAR · EQUIPMENT STUDIO</span><h2>Bonjour Titus</h2><small>Inventaire · configurations · préparation</small></div></div><div class="overview-metrics">${stat(state.items.length,'Articles')}${stat(state.categories.filter(c=>!c.hidden).length,'Catégories')}${stat(state.packs.length,'Configs')}</div>${!state.items.length?'<div class="notice">Ton studio est vide. Importe ta sauvegarde complète ou le CSV fourni (4 références), après vérification de l’aperçu. <button data-nav="data" class="ghost">Importer mes données</button></div>':''}${customizing?customizePanel():''}<div class="dashboard">${state.settings.dashboardOrder.map(k=>`<section class="card module-${k}" data-module="${k}" data-size="${esc(state.settings.dashboardSizes[k]||'auto')}">${modules[k]}</section>`).join('')}</div>`}
function packPhoto(p){const i=p.entries.map(e=>Gear.byId(state,e.itemId)).find(i=>i&&photoKey(i.category+' '+i.name)==='pack');return i?.photo||'assets/pack.webp'}
function customizePanel(){const names={active:'Configuration active',quick:'Accès rapides',readiness:'Préparation',wear:'Usure & état',stock:'Chiffres du stock'};return `<section class="card section-gap"><h2>Disposition du tableau de bord</h2><p class="muted">L’ordre s’applique à tous les écrans ; les largeurs s’appliquent sur tablette et ordinateur. Tous les modules restent disponibles.</p>${state.settings.dashboardOrder.map((k,i)=>`<div class="custom-row"><span>${names[k]}</span><button data-size="${k}">${({auto:'Auto',compact:'Compact',wide:'Large'})[state.settings.dashboardSizes[k]||'auto']}</button><button data-order="${k}" data-dir="-1" ${i===0?'disabled':''} aria-label="Monter ${names[k]}">${icon('up')}</button><button data-order="${k}" data-dir="1" ${i===4?'disabled':''} aria-label="Descendre ${names[k]}">${icon('down')}</button></div>`).join('')}<button data-action="default-layout">Rétablir la disposition</button></section>`}
function itemRow(i){return `<div class="row"><img class="thumb" src="${photo(i)}" alt=""><div class="info"><strong>${esc(i.name)}</strong><small>${esc(i.category||'Sans catégorie')} · ${i.qty} unité(s) · ${grams(i.weight)}</small><small>${esc(i.condition)}${i.wear===null?' · usure inconnue':' · usure '+fmt(i.wear,0)+' %'}</small></div><button data-item="${esc(i.id)}" class="ghost" aria-label="Ouvrir ${esc(i.name)}">${icon('arrow')}</button></div>`}
function inventory(){const items=Gear.filtered(state,filter),categories=state.categories.filter(c=>filter.includeHidden||!c.hidden).map(c=>({name:c.name,count:items.filter(i=>i.category===c.name).length}));if(items.some(i=>!i.category))categories.push({name:'',count:items.filter(i=>!i.category).length});const visibleCats=categories.filter(c=>c.count>0);return heading('Inventaire',`${items.length} référence(s) affichée(s) · ${state.items.length} au total`,`<button data-action="new-item" class="primary">${icon('plus')} Article</button>`)+`<section class="card"><div class="searchbar"><label style="flex:1"><span class="eyebrow">Rechercher un équipement</span><input id="inventory-search" value="${esc(filter.q)}" placeholder="Nom, marque, étiquette, notes…"></label><button data-action="filter" aria-label="Filtres avancés">${icon('filter')}</button></div><div class="between section-gap"><div class="pill-group"><button data-inventory-mode="categories" class="${inventoryMode==='categories'?'active':''}">Catégories</button><button data-inventory-mode="items" class="${inventoryMode==='items'?'active':''}">Articles</button></div>${filter.category||filter.uncategorized||filter.q||filter.location||filter.tags.length||filter.condition||filter.kind||filter.unknown?'<button data-action="clear-filter" class="ghost">Réinitialiser</button>':''}</div>${state.savedFilters.length?`<div class="saved-filter-line">${state.savedFilters.map(f=>`<button data-load-filter="${esc(f.id)}">${esc(f.name)}</button>`).join('')}</div>`:''}${filter.category||filter.location||filter.tags.length?`<p class="inline-note">${esc([filter.category,filter.location,...filter.tags].filter(Boolean).join(' · '))}</p>`:''}</section><div class="section-gap ${inventoryMode==='categories'?'gear-grid':'item-grid'}">${inventoryMode==='categories'?visibleCats.map(c=>`<button class="category-card" data-category="${esc(c.name)}"><img src="${catPhoto(c.name)}" alt=""><div class="category-label"><strong>${esc(c.name||'Sans catégorie')}</strong><span class="badge">${c.count} ${icon('arrow')}</span></div></button>`).join('')||empty('Aucune catégorie avec des articles pour ces critères.',state.items.length?'<button data-action="clear-filter" class="ghost section-gap">Réinitialiser les filtres</button>':'<button data-nav="data" class="primary section-gap">Importer mon inventaire</button>'):items.map(i=>`<button class="item-tile" data-item="${esc(i.id)}"><img src="${photo(i)}" alt="${i.photo?'Photo de '+esc(i.name):'Visuel de catégorie'}"><div class="tile-info"><strong>${esc(i.name)}</strong><small>${esc(i.brand||'')}${i.model?' · '+esc(i.model):''}</small><small>${esc(i.category||'Sans catégorie')} · ${i.qty} possédée(s)</small><div class="tile-bottom"><b>${grams(i.weight)}</b><span class="badge">${({base:'Base',worn:'Porté',consumable:'Consommable'})[i.kind]}</span></div>${i.tags.slice(0,4).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></button>`).join('')||empty('Aucun article pour ces critères.','<button data-action="new-item" class="primary section-gap">Ajouter un article</button>')}</div>`}
function itemPage(){const i=Gear.byId(state,itemId);if(!i)return heading('Article indisponible','Il a peut-être été supprimé.')+'<button data-nav="inventory">Retour à l’inventaire</button>';const used=state.packs.filter(p=>p.entries.some(e=>e.itemId===i.id));let details=detailTab==='details'?`<div class="detail-specs"><div class="row"><small>Poids unitaire</small><strong>${grams(i.weight)}</strong></div><div class="row"><small>Quantité possédée</small><strong>${i.qty}</strong></div><div class="row"><small>Poids du stock de cet article</small><strong>${i.weight===null?'Inconnu':grams(i.weight*i.qty)}</strong></div><div class="row"><small>Type par défaut</small><strong>${({base:'Dans le sac · base',worn:'Porté sur soi',consumable:'Consommable'})[i.kind]}</strong></div><div class="row"><small>Dimensions</small><strong>${esc(i.dimensions||'Non renseignées')}</strong></div><div class="row"><small>Capacité</small><strong>${esc(i.capacity||'Non renseignée')}</strong></div><div class="row"><small>Emplacement</small><strong>${esc(i.location||'Non renseigné')}</strong></div><div class="row"><small>Prix unitaire renseigné</small><strong>${i.price==null?'Inconnu':fmt(i.price)+' €'}</strong></div></div>`:detailTab==='wear'?wearDetail(i):`<section class="card section-gap"><h2>Notes</h2><p class="section-gap" style="white-space:pre-wrap">${esc(i.notes||'Aucune note enregistrée.')}</p></section>`;
 return heading('Fiche équipement','',`<button data-edit-item="${esc(i.id)}" class="primary" aria-label="Modifier l’équipement">${icon('edit')}</button>`)+`<button data-nav="inventory" class="ghost" style="margin-bottom:14px">${icon('back')} Inventaire</button><div class="detail-layout"><div><div class="detail-photo"><img src="${i.photo||'assets/'+(/tente/i.test(i.name)?'tent':photoKey(i.category+' '+i.name))+'.webp'}" alt="${i.photo?'Photo de '+esc(i.name):'Illustration de la catégorie'}">${!i.photo?'<span class="badge">Visuel de catégorie · photo personnelle absente</span>':''}</div>${i.photos?.length?`<div class="mini-gallery">${i.photos.map((p,n)=>`<button data-view-photo="${n}" class="ghost" style="padding:0"><img src="${p}" alt="Photo supplémentaire ${n+1}"></button>`).join('')}</div>`:''}<div class="detail-name"><h1>${esc(i.name)}</h1><p class="muted">${esc([i.brand,i.model].filter(Boolean).join(' ')||'Marque / modèle non renseignés')}</p><div class="tags section-gap"><span class="tag">${esc(i.category||'Sans catégorie')}</span>${i.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></div><div class="actions"><button data-duplicate-item="${esc(i.id)}">${icon('copy')} Dupliquer</button><button data-delete-item="${esc(i.id)}" class="danger">Supprimer</button></div></div><div class="card"><div class="pill-group">${[['details','Détails'],['wear','Usure'],['notes','Notes']].map(([k,n])=>`<button data-detail-tab="${k}" class="${detailTab===k?'active':''}">${n}</button>`).join('')}</div>${details}<div class="section-gap"><h3>Dans mes configurations</h3>${used.length?used.map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><small>${p.entries.find(e=>e.itemId===i.id).qty} unité(s) prévue(s)</small></div><button data-pack="${esc(p.id)}" class="ghost">${icon('arrow')}</button></div>`).join(''):'<p class="muted section-gap">Cet article n’est associé à aucune configuration.</p>'}</div></div></div>`}
function wearDetail(i){return `<div class="section-gap"><div class="between"><h3>${esc(i.condition)}</h3><span class="badge">Seuil ${i.wearLimit} %</span></div>${i.wear===null?'<div class="notice">Usure non renseignée : aucune estimation de durée de vie disponible.</div>':`<div class="progress-label section-gap"><span>Usure enregistrée</span><b>${fmt(i.wear,0)} %</b></div><progress max="100" value="${i.wear}" aria-label="Usure enregistrée"></progress>${i.wear>=i.wearLimit?'<div class="notice">Seuil d’usure atteint : vérifier cet article avant de le préparer.</div>':''}`}<p class="safety">Évaluation personnelle en pourcentage. Aucune date de fin de vie n’est prédite. Le suivi d’entretien, les garanties et les prêts ne sont pas activés.</p></div>`}
function packCard(p){const t=Gear.totals(state,p.entries),m=Gear.missing(state,p.entries);return `<section class="pack-card ${p.id===state.settings.activePackId?'selected':''}"><div class="pack-body"><img src="${packPhoto(p)}" alt="Visuel de sac"><div class="pack-info"><strong>${esc(p.name)}</strong><small>${esc(p.activity||'Configuration personnelle')}${p.days?' · '+fmt(p.days,0)+' jour(s)':''}</small><div class="weight">${mass(t,'bag')}</div><small>${t.unknown?`${t.unknown} unité(s) sans poids`:'Sac au départ'}${m.length?' · '+m.length+' référence(s) manquante(s)':''}</small></div><button data-pack="${esc(p.id)}" class="ghost" aria-label="Ouvrir ${esc(p.name)}">${icon('arrow')}</button></div><div class="pack-footer"><button data-set-active="${esc(p.id)}" class="${p.id===state.settings.activePackId?'primary':'ghost'}">${p.id===state.settings.activePackId?'✓ Active':'Activer'}</button><button data-copy-pack="${esc(p.id)}" class="ghost">Dupliquer</button></div></section>`}
function packs(){return heading('Configurations','Un sac pour chaque départ.',`<button data-action="new-pack" class="primary">${icon('plus')} Config</button>`)+`<div class="grid2">${state.packs.length?state.packs.map(packCard).join(''):empty('Aucune configuration. Ajoute tes articles, puis compose ton premier sac.',`<button data-action="new-pack" class="primary section-gap">Créer une configuration</button>`)}</div><section class="card section-gap"><div class="between"><h2>Comparer deux configurations</h2>${icon('weight')}</div><div class="controls"><label>Première configuration<select id="compare-a"><option value="">Choisir…</option>${state.packs.map(p=>`<option value="${esc(p.id)}" ${compareIds[0]===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Seconde configuration<select id="compare-b"><option value="">Choisir…</option>${state.packs.map(p=>`<option value="${esc(p.id)}" ${compareIds[1]===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div>${comparePanel()}</section>`}
function comparePanel(){const a=state.packs.find(p=>p.id===compareIds[0]),b=state.packs.find(p=>p.id===compareIds[1]);if(!a||!b||a.id===b.id)return '<p class="muted">Sélectionne deux configurations différentes.</p>';const x=Gear.totals(state,a.entries),y=Gear.totals(state,b.entries);return `<div class="table-wrap"><table><thead><tr><th>Poids</th><th>${esc(a.name)}</th><th>${esc(b.name)}</th><th>Écart connu B − A</th></tr></thead><tbody>${[['base','Base'],['worn','Porté'],['consumable','Consommables'],['bag','Sac au départ'],['total','Charge en marche']].map(([k,n])=>`<tr><td>${n}</td><td>${mass(x,k)}</td><td>${mass(y,k)}</td><td>${fmt((y[k]-x[k])/1000,3)} kg${x.unknown||y.unknown?' · partiel':''}</td></tr>`).join('')}<tr><td>Unités sans poids</td><td>${x.unknown}</td><td>${y.unknown}</td><td>${y.unknown-x.unknown}</td></tr></tbody></table></div><p class="safety">Les deux configurations utilisent le même inventaire, sans retirer de stock. Un écart avec des poids inconnus ne représente pas l’écart complet.</p>`}
function donut(t){const values=[{key:'base',label:'Base',color:'var(--red)'},{key:'consumable',label:'Consommables',color:'var(--orange)'},{key:'worn',label:'Porté sur soi',color:'var(--sage)'}],total=t.total;let offset=0;const circles=values.map(v=>{const size=total?t[v.key]/total*100:0,el=`<circle cx="110" cy="110" r="79" fill="none" stroke="${v.color}" stroke-width="19" pathLength="100" stroke-dasharray="${size} ${100-size}" stroke-dashoffset="${-offset}" transform="rotate(-90 110 110)"><title>${v.label} : ${grams(t[v.key])}</title></circle>`;offset+=size;return el}).join('');return `<div class="donut-wrap"><svg class="donut-svg" viewBox="0 0 220 220" role="img" aria-label="Répartition des poids connus ; ${t.unknown} unités sans poids"><circle cx="110" cy="110" r="79" fill="none" stroke="var(--line)" stroke-width="19"/>${circles}<text x="110" y="108" text-anchor="middle" class="donut-label">${t.unknown&&total===0?'?':(t.unknown?'≥ ':'')+fmt(total/1000,3)+' kg'}</text><text x="110" y="128" text-anchor="middle" class="donut-sub">${t.unknown?'Poids connu partiel':'Charge totale en marche'}</text></svg><div class="weight-legend">${values.map(v=>`<div class="weight-line"><span><i class="swatch" style="background:${v.color}"></i>${v.label}</span><b>${mass(t,v.key)}</b></div>`).join('')}<div class="weight-line"><span>Sans poids</span><b>${t.unknown} unité(s)</b></div><p class="fixed-label">${unknownLabel(t)}. La répartition représente uniquement les grammes connus.</p></div></div>`}
function packPage(){const p=state.packs.find(p=>p.id===packId);if(!p)return heading('Configuration indisponible')+'<button data-nav="packs">Retour aux configurations</button>';const sim=simulation?.packId===p.id,entries=sim?simulation.entries:p.entries,t=Gear.totals(state,entries),m=Gear.missing(state,entries);let content='';
 if(packTab==='history')content=`<section class="card section-gap"><div class="between"><h2>Historique des poids</h2><button data-snapshot="${esc(p.id)}">Enregistrer cet état</button></div><p class="muted">Valeurs capturées à la date indiquée. Les modifications futures des articles ne réécrivent pas ces états.</p>${p.history.length?p.history.slice().reverse().map(h=>`<div class="history-row"><div class="between"><strong>${when(h.at)}</strong><span class="badge">${grams(h.totals.bag)}${h.totals.unknown?' · partiel':''}</span></div><small>${esc(h.reason)}</small><details><summary>Détail de ${h.rows.length} références</summary><div class="table-wrap"><table><tr><th>Article</th><th>Quantité</th><th>Poids unitaire</th><th>Type</th></tr>${h.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.qty}</td><td>${grams(r.weight)}</td><td>${esc(r.kind)}</td></tr>`).join('')}</table></div></details></div>`).join(''):'<div class="empty">Aucun état enregistré. Aucun historique n’a été inventé.</div>'}</section>`;
 else if(packTab==='categories')content=`<section class="card section-gap"><h2>Poids par catégorie</h2>${t.categories.map(c=>`<div class="row"><div class="info"><strong>${esc(c.name)}</strong><small>${c.units} unité(s)${c.unknown?' · '+c.unknown+' poids inconnu(s)':''}</small></div><b>${c.unknown?'≥ ':''}${grams(c.weight)}</b></div>`).join('')||'<div class="empty">Configuration vide.</div>'}<p class="safety">Sous-totaux fondés sur les poids connus. Une catégorie avec des poids manquants n’a pas de total complet.</p></section>`;
 else content=`<section class="card section-gap"><div class="between"><h2>${sim?'Simulation du contenu':'Équipement & quantités'}</h2><button data-add-entry="${esc(p.id)}" class="primary">${icon('plus')} Ajouter</button></div>${entries.length?`<div class="table-wrap"><table class="item-table"><thead><tr><th>Article</th><th>Type dans ce sac</th><th>Quantité</th><th>Poids</th><th></th></tr></thead><tbody>${entries.map(e=>{const i=Gear.byId(state,e.itemId);return `<tr><td><img src="${photo(i)}" alt=""><button data-item="${esc(i.id)}" class="ghost" style="padding:0;border:0;min-height:30px;text-align:left">${esc(i.name)}</button><small class="block">Stock : ${i.qty}${e.qty>i.qty?' · MANQUE '+(e.qty-i.qty):''}</small></td><td><select data-entry-kind="${esc(e.itemId)}" aria-label="Type de poids ${esc(i.name)}">${[['base','Base'],['worn','Porté'],['consumable','Consommable']].map(([k,n])=>`<option value="${k}" ${(e.kind||i.kind)===k?'selected':''}>${n}</option>`).join('')}</select></td><td><input data-entry-qty="${esc(e.itemId)}" aria-label="Quantité ${esc(i.name)}" type="number" min="1" step="1" max="1000000" value="${e.qty}" style="width:74px"></td><td>${i.weight===null?'Inconnu':grams(i.weight*e.qty)}</td><td><button data-remove-entry="${esc(e.itemId)}" class="ghost" aria-label="Retirer ${esc(i.name)}">${icon('close')}</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Ajoute un équipement pour commencer le calcul.</div>'}</section>`;
 return heading(esc(p.name),`${esc(p.activity||'Configuration personnelle')}${p.days?' · '+fmt(p.days,0)+' jour(s)':''}`,`<button data-edit-pack="${esc(p.id)}" aria-label="Modifier la configuration">${icon('edit')}</button>`)+`<button data-nav="packs" class="ghost" style="margin-bottom:14px">${icon('back')} Configurations</button>${sim?`<div class="simulation"><div class="between"><strong>Simulation · non enregistrée</strong><button data-action="cancel-simulation">Fermer</button></div><p class="muted">Les quantités et types ci-dessous ne changent pas la configuration originale.</p><button data-action="save-simulation" class="primary section-gap">Enregistrer comme nouvelle configuration</button></div>`:''}<div class="pack-detail-grid"><section class="card"><div class="active-pack"><img src="${packPhoto(p)}" alt="Visuel de sac"><div class="pack-info"><h3>${esc(p.name)}</h3><small>${entries.length} références · ${t.units} unités</small><div class="weight">${mass(t,'bag')}</div><small>Sac au départ</small></div></div><div class="actions"><button data-set-active="${esc(p.id)}" class="${p.id===state.settings.activePackId?'primary':'ghost'}">${p.id===state.settings.activePackId?'✓ Configuration active':'Activer'}</button><button data-create-list="${esc(p.id)}">${icon('prep')} Préparer</button>${!sim?`<button data-start-simulation="${esc(p.id)}">Simuler</button>`:''}<button data-exchange="${esc(p.id)}">Exporter l’échange</button></div>${m.length?`<div class="notice">${m.length} référence(s) en quantité insuffisante : ${m.map(r=>esc(Gear.byId(state,r.itemId)?.name)+' (−'+r.missing+')').join(', ')}.</div>`:''}${p.notes?`<p class="muted section-gap" style="white-space:pre-wrap">${esc(p.notes)}</p>`:''}</section><section class="card"><div class="between"><h2>Calculateur de sac</h2>${icon('weight')}</div>${donut(t)}<div class="calc-total"><span>Sac au départ<br><small>Base + consommables</small></span><strong>${mass(t,'bag')}</strong></div><div class="calc-total"><span>Charge en marche<br><small>Sac + porté sur soi</small></span><strong>${mass(t)}</strong></div></section></div><div class="pill-group section-gap">${[['content','Équipement'],['categories','Catégories'],['history','Historique']].map(([k,n])=>`<button data-pack-tab="${k}" class="${packTab===k?'active':''}">${n}</button>`).join('')}</div>${content}`}
function prep(){let list=state.lists.find(l=>l.id===listId)||state.lists[0];if(list)listId=list.id;if(!list)return heading('Préparation','Chaque départ, prêt dans le détail.',`<button data-action="new-list" class="primary">${icon('plus')} Liste</button>`)+`<section class="card">${empty('Crée une liste libre ou une liste issue d’une configuration.',`<button data-action="new-list" class="primary section-gap">Créer ma liste</button>`)}</section>`;const r=Gear.ready(state,list),groups=[...new Set(r.rows.map(e=>e.item.category||'Sans catégorie'))];return heading('Préparation','Les quantités comptent autant que les cases.',`<button data-action="new-list" class="primary">${icon('plus')} Liste</button>`)+`<div class="grid2"><section class="card"><div class="controls"><label style="flex:1">Liste de préparation<select id="list-select">${state.lists.map(l=>`<option value="${esc(l.id)}" ${l.id===list.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label><button data-edit-list="${esc(list.id)}" aria-label="Modifier cette liste">${icon('edit')}</button></div><div class="progress-label"><span>Équipement préparé · ${r.prepared}/${r.required} unités</span><b>${r.percent} %</b></div><progress max="100" value="${r.percent}" aria-label="Progression de la liste"></progress>${r.missing?`<div class="notice">${r.missing} unité(s) demandée(s) dépassent le stock possédé. Une case cochée ne peut pas rendre ces unités disponibles.</div>`:''}${list.packId?`<p class="muted section-gap">Configuration liée : ${esc(state.packs.find(p=>p.id===list.packId)?.name||'—')}</p>`:''}${Gear.listDiff(state,list)?`<div class="notice">Le contenu de la configuration a changé. <button data-sync-list="${esc(list.id)}">Actualiser la liste</button></div>`:''}<div class="actions"><button data-add-list-entry="${esc(list.id)}" class="primary">${icon('plus')} Article</button><button data-delete-list="${esc(list.id)}" class="danger">Supprimer la liste</button></div></section><section class="card"><div class="between"><h2>À préparer</h2><span class="badge">${r.rows.length} références</span></div>${groups.map((cat,idx)=>{const rows=r.rows.filter(e=>(e.item.category||'Sans catégorie')===cat),prepared=rows.reduce((n,e)=>n+e.prepared,0),total=rows.reduce((n,e)=>n+e.qty,0);return `<details class="prep-group" data-prep-group="${esc(list.id+'::'+cat)}" ${groups.length<=3||idx===0?'open':''}><summary><span>${icon(prepared===total?'check':'inventory')} ${esc(cat)}</span><span class="badge">${prepared}/${total} ${icon('arrow')}</span></summary>${rows.map(e=>`<div class="prep-row"><input type="checkbox" data-ready-all="${esc(e.itemId)}" aria-label="Préparé ${esc(e.item.name)}" ${e.prepared===e.qty?'checked':''}><div class="info"><strong>${esc(e.item.name)}</strong><small>Demandé ${e.qty} · stock ${e.available}${e.missing?' · manque '+e.missing:''}</small><small>${e.prepared===e.qty?'Prêt':e.prepared>0?'Partiellement préparé':'À préparer'}</small></div><div class="quantity-control"><label>Prêt<input data-ready-qty="${esc(e.itemId)}" type="number" min="0" max="${e.qty}" value="${e.readyQty}" aria-label="Unités prêtes ${esc(e.item.name)}"></label><label>Qté<input data-list-qty="${esc(e.itemId)}" type="number" min="1" max="1000000" value="${e.qty}" aria-label="Unités demandées ${esc(e.item.name)}"></label></div><button data-remove-list-entry="${esc(e.itemId)}" class="ghost" aria-label="Retirer ${esc(e.item.name)}">${icon('close')}</button></div>`).join('')}</details>`}).join('')||'<div class="empty">Liste vide. Ajoute les articles à préparer.</div>'}</section></div>`}
function wear(){const items=state.items.filter(i=>wearFilter==='all'||wearFilter==='alerts'&&alerts().some(x=>x.id===i.id)||wearFilter==='unknown'&&i.wear===null);return heading('Usure & état','Un suivi fondé sur tes propres évaluations.')+`<div class="controls"><label>Afficher<select id="wear-filter"><option value="all">Tous les articles</option><option value="alerts" ${wearFilter==='alerts'?'selected':''}>Seuils atteints / à remplacer</option><option value="unknown" ${wearFilter==='unknown'?'selected':''}>Usure inconnue</option></select></label></div><div class="grid2">${items.map(i=>`<section class="wear-tile"><img src="${photo(i)}" alt="${i.photo?'Photo personnelle':'Visuel de catégorie'}"><div class="info"><div class="between"><strong>${esc(i.name)}</strong><button data-item="${esc(i.id)}" class="ghost" aria-label="Ouvrir ${esc(i.name)}">${icon('arrow')}</button></div><small>${esc([i.brand,i.model].filter(Boolean).join(' '))}</small><small>État : ${esc(i.condition)}</small>${i.wear===null?'<span class="badge">Usure inconnue</span>':`<div class="progress-label"><span>Usure enregistrée</span><b>${fmt(i.wear,0)} %</b></div><progress max="100" value="${i.wear}" aria-label="Usure de ${esc(i.name)}"></progress><small>Seuil : ${i.wearLimit} %${i.wear>=i.wearLimit?' · À vérifier':''}</small>`}</div></section>`).join('')||empty('Aucun article pour ce filtre.')}</div><p class="safety">L’usure n’est pas déduite automatiquement du temps écoulé. Aucun suivi d’entretien, de garantie ou de prêt n’est activé.</p>`}
function wishes(){return heading('Souhaits & remplacements','L’équipement à prévoir, avant de l’acquérir.',`<button data-action="new-wish" class="primary">${icon('plus')} Souhait</button>`)+`<div class="grid2">${state.wishes.map(w=>`<section class="card"><div class="between"><h2>${esc(w.name)}</h2><span class="badge ${w.priority==='Indispensable'?'red':''}">${esc(w.priority)}</span></div>${w.price===null?'<p class="muted">Budget inconnu</p>':`<p>${fmt(w.price)} € <small>budget indicatif</small></p>`}${w.replacementFor?`<p class="muted">Remplace : ${esc(Gear.byId(state,w.replacementFor)?.name||'—')}</p>`:''}<p class="muted section-gap" style="white-space:pre-wrap">${esc(w.notes)}</p><div class="actions"><button data-acquire-wish="${esc(w.id)}" class="primary">Acquis → Inventaire</button><button data-edit-wish="${esc(w.id)}">Modifier</button><button data-delete-wish="${esc(w.id)}" class="danger">Supprimer</button></div></section>`).join('')||empty('Aucun souhait enregistré.',`<button data-action="new-wish" class="primary section-gap">Ajouter un souhait</button>`)}</div>`}
function stats(){const t=stockTotals(),values=state.items.filter(i=>i.price!==null&&i.price!==undefined),totalValue=values.reduce((n,i)=>n+i.price*i.qty,0),tags=[...new Set(state.items.flatMap(i=>i.tags))];return heading('Statistiques','Poids, répartition et valeur du stock renseigné.')+`<div class="number-grid">${stat(state.items.length,'Références','inventory')}${stat(t.units,'Unités possédées','packs')}${stat(values.length?fmt(totalValue)+' €':'—',`${values.length}/${state.items.length} références avec prix`,'stats')}${stat(alerts().length,'Articles à vérifier','wear')}</div><div class="grid2 section-gap"><section class="card"><h2>Répartition des poids du stock</h2>${donut(t)}<p class="muted section-gap">Il s’agit de la totalité des unités possédées, pas du sac actif. Les articles masqués restent inclus dans ce calcul.</p></section><section class="card"><h2>Catégories du stock</h2>${t.categories.map(c=>`<div class="row"><div class="info"><strong>${esc(c.name)}</strong><small>${c.units} unité(s)${c.unknown?' · '+c.unknown+' poids inconnu(s)':''}</small></div><b>${c.unknown?'≥ ':''}${grams(c.weight)}</b></div>`).join('')||'<div class="empty">Aucun article.</div>'}</section><section class="card"><h2>Étiquettes</h2><div class="tags section-gap">${tags.map(t=>`<button data-tag-filter="${esc(t)}" class="tag">${esc(t)} · ${state.items.filter(i=>i.tags.includes(t)).length}</button>`).join('')||'<p class="muted">Aucune étiquette renseignée.</p>'}</div></section><section class="card"><h2>Emplacements hiérarchiques</h2>${Gear.locations(state).map(p=>`<div class="row"><button data-location-filter="${esc(p)}" class="ghost">${'↳ '.repeat(Math.max(0,Gear.pathParts(p).length-1))}${esc(Gear.pathParts(p).at(-1))}</button><span class="badge">${state.items.filter(i=>Gear.pathKey(i.location)===Gear.pathKey(p)||Gear.pathKey(i.location).startsWith(Gear.pathKey(p)+'/')).length}</span></div>`).join('')||'<p class="muted section-gap">Aucun emplacement renseigné.</p>'}</section></div>`}
function dataPage(){return heading('Données & sauvegardes','Tes données restent sur cet appareil et cette adresse web.')+`<div class="grid2"><section class="card"><h2>Sauvegarde complète JSON</h2><p class="muted">Inventaire, photos, catégories, étiquettes, emplacements, sacs, historique, listes, souhaits et préférences.</p><div class="actions"><button data-action="backup" class="primary">${icon('download')} Exporter tout le studio</button><button data-action="csv-export">Exporter l’inventaire CSV</button></div><p class="safety">Le CSV ne contient pas les photos, sacs ou listes. Il ne remplace pas une sauvegarde complète.</p></section><section class="card"><h2>Restaurer une sauvegarde</h2><p class="muted">Compatible avec les JSON complets MY GEAR v1 et v2. Aperçu et contrôle avant remplacement ; une copie locale de l’état précédent est conservée.</p><label class="section-gap">Fichier JSON<input type="file" id="restore-input" accept=".json,application/json"></label><div id="restore-preview">${restorePreview()}</div><div class="actions"><button data-action="before-export">Exporter l’état avant restauration</button><button data-action="raw-export" class="ghost">Récupération brute</button></div></section><section class="card"><h2>Importer un inventaire CSV</h2><p class="muted">Ajout / rapprochement avec aperçu des conflits. Les photos et les autres modules ne sont pas effacés.</p><label class="section-gap">Fichier CSV<input id="csv-input" type="file" accept=".csv,text/csv"></label><button data-action="provided-csv" class="ghost section-gap">Examiner le CSV fourni · 4 références</button><div id="csv-preview">${csvPreview()}</div></section><section class="card"><h2>État du stockage et du cache</h2><div class="metric-line"><span>Références / configurations</span><b>${state.items.length} / ${state.packs.length}</b></div><div class="metric-line"><span>Stockage</span><b>IndexedDB · schéma 2</b></div><div class="metric-line"><span>Dernier enregistrement</span><b style="font-size:12px">${when(state.updated)}</b></div><div class="metric-line"><span>Ressources hors ligne</span><b id="offline-status" class="data-status">Vérification…</b></div><div class="actions"><button data-action="check-cache">Vérifier le cache</button><button data-action="persistent">Demander un stockage persistant</button></div><p class="safety">Une suppression des données du navigateur peut effacer l’inventaire. Garde un JSON complet en dehors de l’application.</p></section><section class="card"><h2>Échanges futurs</h2><p class="muted">Chaque configuration peut être exportée au format documenté <code>nexus.gear</code> pour un échange manuel futur avec TRAIL COMMAND, VOYAGER ou NEXUS.</p><p class="safety">Aucune synchronisation, aucun compte ni service cloud ne sont actifs. Le studio reste indépendant.</p><button data-nav="packs" class="ghost section-gap">Choisir une configuration</button></section></div>`}
function restorePreview(){return pendingRestore?`<div class="notice"><strong>Sauvegarde contrôlée</strong><p>${pendingRestore.items.length} articles · ${pendingRestore.packs.length} configurations · ${pendingRestore.lists.length} listes · ${pendingRestore.wishes.length} souhaits.</p><p>La restauration remplacera tous les modules et préférences. Une copie préalable locale sera créée en même temps que le remplacement.</p><button data-action="restore" class="primary">Confirmer le remplacement complet</button></div>`:''}
function csvPreview(){if(!pendingCSV)return '';return `<div class="notice"><strong>Aperçu CSV</strong><p>${pendingCSV.newCount} ajout(s) · ${pendingCSV.updateCount} rapprochement(s) · ${pendingCSV.conflicts} conflit(s) · ${pendingCSV.unknown} poids inconnu(s).</p>${pendingCSV.records.slice(0,8).map(r=>`<p><b>${esc(r.item.name)}</b> · ${r.item.qty} unité(s) · ${grams(r.item.weight)} · ${esc(({base:'Base',worn:'Porté sur soi',consumable:'Consommable'})[r.item.kind])}${r.conflicts.length?' · conflits : '+esc(r.conflicts.join(', ')):''}</p>`).join('')}<label>Valeurs en conflit<select id="csv-priority"><option value="local">Conserver les valeurs locales renseignées</option><option value="csv">Utiliser les valeurs du CSV</option></select></label><p>Les valeurs et types de poids sont ceux du fichier. Vérifie notamment les articles classés « Porté sur soi » ; aucun reclassement n’est supposé.</p><button data-action="commit-csv" class="primary">Confirmer l’import CSV</button></div>`}
function settings(){return heading('Paramètres','Un studio à ton image.')+`<div class="grid2"><section class="card"><h2>Apparence et tableau de bord</h2><label class="section-gap">Thème<select id="theme-select">${[['auto','Automatique · système'],['dark','Anthracite, olive & sauge'],['light','Ivoire & olive']].map(([k,n])=>`<option value="${k}" ${state.settings.theme===k?'selected':''}>${n}</option>`).join('')}</select></label><button data-action="customize-home" class="ghost section-gap">Personnaliser les modules d’accueil</button><label class="check section-gap"><input id="trek-only" type="checkbox" ${state.settings.hiddenGeneral?'checked':''}><span>Afficher uniquement les articles étiquetés « trek » dans l’inventaire</span></label><p class="muted">Les autres articles restent conservés et disponibles dans les configurations. Les calculs de stock complet ne les excluent pas.</p></section><section class="card"><h2>Catégories personnalisées</h2><p class="muted">Masquer une catégorie modifie son affichage, sans supprimer ses articles.</p><button data-action="new-category" class="primary section-gap">${icon('plus')} Catégorie</button>${state.categories.map(c=>`<div class="category-manage"><input type="checkbox" data-category-visible="${esc(c.id)}" ${!c.hidden?'checked':''} aria-label="Afficher ${esc(c.name)}"><div class="info"><strong>${esc(c.name)}</strong><small>${state.items.filter(i=>i.category===c.name).length} article(s)</small></div><button data-rename-category="${esc(c.id)}">Renommer</button></div>`).join('')}</section><section class="card"><h2>Installation & mises à jour</h2><p class="muted section-gap">Ouvre le site en HTTPS dans Chrome sur Samsung, puis utilise Installer l’application / Ajouter à l’écran d’accueil. Vérifie le cache, puis le mode avion après une première ouverture complète.</p><div class="actions"><button data-action="install" class="primary">Installer MY GEAR</button><button data-action="check-update">Rechercher une mise à jour</button></div><p class="safety">Lorsqu’une mise à jour est prête, son activation attend ta confirmation. Aucun effacement des données locales pendant le remplacement du cache.</p></section><section class="card"><h2>Filtres sauvegardés</h2>${state.savedFilters.map(f=>`<div class="row"><div class="info"><strong>${esc(f.name)}</strong><small>${esc([f.filter.category,f.filter.location,...f.filter.tags].filter(Boolean).join(' · ')||'Recherche personnalisée')}</small></div><button data-load-filter="${esc(f.id)}">Ouvrir</button><button data-delete-filter="${esc(f.id)}" class="danger" aria-label="Supprimer le filtre ${esc(f.name)}">${icon('close')}</button></div>`).join('')||'<p class="muted section-gap">Aucun filtre sauvegardé. Crée-en un depuis l’inventaire.</p>'}</section><section class="card"><h2>Emplacements hiérarchiques</h2><p class="muted">Dans une fiche, sépare les niveaux par « / », par exemple Maison / Placard / Étagère 2. Un filtre sur Maison retrouve aussi tous ses sous-emplacements.</p>${Gear.locations(state).map(p=>`<div class="row"><span class="muted">${esc(p)}</span><button data-location-filter="${esc(p)}" class="ghost">Voir</button></div>`).join('')||'<p class="muted section-gap">Aucun emplacement renseigné.</p>'}</section><section class="card"><h2>Equipment Studio 2.0</h2><p class="muted section-gap">Polices Manrope / Inter locales, identité olive/sauge/anthracite, visuels décoratifs issus de la maquette originale. Les photos personnelles sont stockées localement.</p><p class="safety">Usure déclarative uniquement. Pas de suivi d’entretien, prêts, garanties ni prédiction automatique de durée de vie. Une recherche Web automatique n’est pas active.</p></section></div>`}
function showSheet(title,body,wide=false){$('sheet').classList.toggle('dialog-wide',wide);$('sheetBody').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="Fermer">${icon('close')}</button></div>${body}`;if(!$('sheet').open)$('sheet').showModal()}
function closeSheet(){if($('sheet').open)$('sheet').close();if(externalPending){externalPending=false;GearStore.load().then(r=>{state=r.data;render()}).catch(e=>{blocked=e.message;render()})}}
const input=(label,name,type='text',value='',attributes='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attributes}></label>`;
function editItem(id=null,wishId=null){const item=Gear.byId(state,id),wish=state.wishes.find(w=>w.id===wishId);editingItemId=item?.id||null;acquiringWishId=wish?.id||null;photoDraft=[item?.photo,...(item?.photos||[])].filter(Boolean);const i=item||{name:wish?.name||'',category:'',qty:1,weight:null,kind:'base',condition:'Neuf',location:'',tags:[],wear:null,wearLimit:80,notes:wish?.notes||'',brand:'',model:'',dimensions:'',capacity:'',price:null};
 showSheet(item?'Modifier l’équipement':wish?'Acquisition → nouvel équipement':'Nouvel équipement',`${wish?'<div class="notice">L’enregistrement de cette fiche ajoutera l’article à l’inventaire et retirera le souhait en une seule opération. Le budget indicatif n’est pas considéré comme un prix payé.</div>':''}<form id="item-form" data-unit="g" class="fields"><span class="form-section">Fiche de l’article</span>${input('Nom *','name','text',i.name,'required maxlength="160"')}${input('Catégorie','category','text',i.category,'list="category-options" maxlength="160"')}<datalist id="category-options">${state.categories.map(c=>`<option value="${esc(c.name)}"></option>`).join('')}</datalist>${input('Marque','brand','text',i.brand,'maxlength="1000"')}${input('Modèle','model','text',i.model,'maxlength="1000"')}${input('Quantité possédée','qty','number',i.qty,'required min="0" max="1000000" step="1"')}${input('Poids unitaire (vide = inconnu)','weight','number',i.weight,'min="0" max="100000000" step="0.1"')}<label>Unité de saisie<select name="weightUnit" id="weight-unit"><option value="g">Grammes (g)</option><option value="kg">Kilogrammes (kg)</option></select></label><label>Type par défaut<select name="kind">${[['base','Dans le sac · base'],['worn','Porté sur soi'],['consumable','Consommable']].map(([k,n])=>`<option value="${k}" ${i.kind===k?'selected':''}>${n}</option>`).join('')}</select></label>${input('Dimensions','dimensions','text',i.dimensions,'maxlength="1000" placeholder="Ex. 210 × 120 × 100 cm"')}${input('Capacité','capacity','text',i.capacity,'maxlength="1000" placeholder="Ex. 2 personnes / 60 L"')}${input('Emplacement · niveaux séparés par /','location','text',i.location,'list="location-options" maxlength="1000" placeholder="Maison / Placard / Étagère"')}<datalist id="location-options">${Gear.locations(state).map(p=>`<option value="${esc(p)}"></option>`).join('')}</datalist>${input('Étiquettes · séparées par des virgules','tags','text',i.tags.join(', '),'placeholder="trek, hiver, indispensable"')}${input('Prix unitaire payé (€) · facultatif','price','number',i.price,'min="0" max="100000000" step="0.01"')}<span class="form-section">Usure & état</span><label>État<select name="condition">${[...new Set(['Neuf','Bon','À surveiller','À remplacer','Hors service',i.condition])].map(v=>`<option ${i.condition===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>${input('Usure enregistrée (%) · vide = inconnue','wear','number',i.wear,'min="0" max="100" step="1"')}${input('Seuil d’alerte d’usure (%)','wearLimit','number',i.wearLimit,'required min="1" max="100" step="1"')}<label class="wide">Notes<textarea name="notes" maxlength="200000">${esc(i.notes)}</textarea></label><span class="form-section">Photos personnelles</span><label class="wide">Ajouter jusqu’à 4 photos au total<input id="item-photos" type="file" accept="image/*" multiple></label><small class="wide">Compression locale, sans envoi à un serveur. Le premier visuel devient la photo principale.</small><div id="photo-draft" class="photo-edit-grid wide">${draftPhotos()}</div><button class="primary wide" type="submit">${wish?'Confirmer l’acquisition et enregistrer':'Enregistrer l’équipement'}</button></form>`,true)}
function draftPhotos(){return photoDraft.map((p,n)=>`<div class="photo-edit"><img src="${p}" alt="Photo ${n+1}"><button type="button" data-remove-photo="${n}" aria-label="Retirer photo ${n+1}">×</button></div>`).join('')}
function packEditor(id=null,preset=null){const p=state.packs.find(p=>p.id===id)||preset||{name:'',activity:'Randonnée',days:null,notes:''};showSheet(id?'Modifier la configuration':'Nouvelle configuration',`<form id="pack-form" data-pack-id="${esc(id||'')}" class="fields">${input('Nom *','name','text',p.name,'required maxlength="160"')}${input('Activité','activity','text',p.activity,'list="activity-options" maxlength="160"')}<datalist id="activity-options"><option>Randonnée</option><option>Trekking</option><option>Course</option><option>Marathon</option><option>Voyage</option><option>Bivouac</option></datalist>${input('Durée (jours) · facultative','days','number',p.days,'min="1" max="3650" step="1"')}<label class="wide">Notes<textarea name="notes" maxlength="200000">${esc(p.notes)}</textarea></label><button class="primary wide">Enregistrer la configuration</button>${id?`<button type="button" data-delete-pack="${esc(id)}" class="danger wide">Supprimer la configuration</button>`:''}</form>`)}
function listEditor(id=null,fromPack=null){const l=state.lists.find(l=>l.id===id)||{name:fromPack?state.packs.find(p=>p.id===fromPack)?.name+' · préparation':'',packId:fromPack};showSheet(id?'Modifier la liste':'Nouvelle liste',`<form id="list-form" data-list-id="${esc(id||'')}" class="fields">${input('Nom *','name','text',l.name,'required maxlength="160"')}<label>Configuration associée<select name="packId"><option value="">Liste libre</option>${state.packs.map(p=>`<option value="${esc(p.id)}" ${l.packId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><p class="wide muted">${id?'Changer l’association ne remplace pas les cases préparées. L’actualisation du contenu reste explicite.':'Une configuration choisie fournit les articles et quantités de départ. Les unités sont initialement à préparer.'}</p><button class="primary wide">Enregistrer la liste</button></form>`)}
function wishEditor(id=null){const w=state.wishes.find(w=>w.id===id)||{name:'',priority:'Facultatif',price:null,notes:'',replacementFor:null};showSheet(id?'Modifier le souhait':'Nouveau souhait',`<form id="wish-form" data-wish-id="${esc(id||'')}" class="fields">${input('Nom *','name','text',w.name,'required maxlength="160"')}<label>Priorité<select name="priority">${['Indispensable','Facultatif','Remplacement'].map(v=>`<option ${w.priority===v?'selected':''}>${v}</option>`).join('')}</select></label>${input('Budget indicatif (€) · facultatif','price','number',w.price,'min="0" max="100000000" step="0.01"')}<label>Remplace cet article (facultatif)<select name="replacementFor"><option value="">Aucun article associé</option>${state.items.map(i=>`<option value="${esc(i.id)}" ${w.replacementFor===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select></label><label class="wide">Notes<textarea name="notes" maxlength="200000">${esc(w.notes)}</textarea></label><button class="primary wide">Enregistrer le souhait</button></form>`)}
function entryEditor(type,id){if(!state.items.length){toast('Ajoute un article dans l’inventaire avant de composer une liste ou un sac.');return}showSheet(type==='pack'?'Ajouter à la configuration':'Ajouter à la préparation',`<form id="entry-form" data-type="${type}" data-target-id="${esc(id)}" class="fields"><label class="wide">Article<select name="itemId">${state.items.map(i=>`<option value="${esc(i.id)}">${esc(i.name)} · ${i.qty} en stock</option>`).join('')}</select></label>${input('Quantité demandée','qty','number',1,'required min="1" max="1000000" step="1"')}<p class="wide muted">Si l’article est déjà présent, la quantité demandée est augmentée ; une seconde ligne n’est pas créée.</p><button class="primary wide">Ajouter</button></form>`)}
function filterSheet(){const options=(values,current)=>`<option value="">Tous</option>${[...new Set(values)].filter(Boolean).sort((a,b)=>a.localeCompare(b,'fr')).map(v=>`<option value="${esc(v)}" ${current===v?'selected':''}>${esc(v)}</option>`).join('')}`,tags=[...new Set(state.items.flatMap(i=>i.tags))].sort();showSheet('Recherche & filtres',`<form id="filter-form" class="fields">${input('Recherche','q','text',filter.q)}<label>Catégorie<select name="category"><option value="">Toutes</option><option value="__none__" ${filter.uncategorized?'selected':''}>Sans catégorie</option>${state.categories.map(c=>`<option value="${esc(c.name)}" ${filter.category===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Emplacement et descendants<select name="location">${options(Gear.locations(state),filter.location)}</select></label><label>État<select name="condition">${options(state.items.map(i=>i.condition),filter.condition)}</select></label><label>Type<select name="kind"><option value="">Tous</option>${[['base','Base'],['worn','Porté'],['consumable','Consommable']].map(([k,n])=>`<option value="${k}" ${filter.kind===k?'selected':''}>${n}</option>`).join('')}</select></label><label>Étiquettes<select name="tagMode"><option value="all" ${filter.tagMode==='all'?'selected':''}>Toutes les étiquettes choisies</option><option value="any" ${filter.tagMode==='any'?'selected':''}>Au moins une étiquette</option></select></label><div class="wide tags">${tags.map(t=>`<label class="check-inline"><input type="checkbox" name="tag" value="${esc(t)}" ${filter.tags.includes(t)?'checked':''}><span>${esc(t)}</span></label>`).join('')||'<p class="muted">Aucune étiquette disponible.</p>'}</div><label class="check-inline"><input type="checkbox" name="unknown" ${filter.unknown?'checked':''}>Poids inconnus seulement</label><label class="check-inline"><input type="checkbox" name="includeHidden" ${filter.includeHidden?'checked':''}>Inclure les catégories masquées</label>${input('Nom pour sauvegarder ces critères (facultatif)','saveName','text','','maxlength="100"')}<button class="primary wide">Appliquer les critères</button></form>`)}
function download(name,content,type='application/json'){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function exportBackup(data=state){Gear.validate(data);download('MY_GEAR_sauvegarde_complete_'+localDate()+'.json',JSON.stringify(Gear.backup(data),null,2));toast('Sauvegarde complète générée avec les photos et tous les modules.')}
async function readJSON(file){if(file.size>64*1024*1024)throw Error('JSON supérieur à 64 Mo');return Gear.normalize(JSON.parse(await file.text()))}
async function csvFromText(raw){pendingCSV=Gear.csvPreview(state,Gear.parseCSV(raw));const el=$('csv-preview');if(el)el.innerHTML=csvPreview()}
function mutateEntries(itemId,fn){const p=state.packs.find(p=>p.id===packId);if(!p)return Promise.resolve(false);const entries=Gear.copy(simulation?.packId===p.id?simulation.entries:p.entries);fn(entries);if(simulation?.packId===p.id){const draft=Gear.copy(state);draft.packs.find(x=>x.id===p.id).entries=entries;Gear.validate(draft);simulation.entries=entries;render();return Promise.resolve(true)}return commit(d=>Gear.updateEntries(d,p.id,entries))}
function chooseActive(){if(!state.packs.length)return packEditor();showSheet('Configuration active',`<div class="stack">${state.packs.map(p=>`<button data-set-active="${esc(p.id)}" class="${p.id===state.settings.activePackId?'primary':''}">${esc(p.name)} · ${mass(Gear.totals(state,p.entries),'bag')}</button>`).join('')}</div>`)}
function categoryEditor(id=null){const c=state.categories.find(c=>c.id===id);showSheet(c?'Renommer la catégorie':'Nouvelle catégorie',`<form id="category-form" data-category-id="${esc(id||'')}" class="fields">${input('Nom *','name','text',c?.name||'','required maxlength="160"')}<p class="muted wide">${c?'Le nouveau nom sera appliqué aux articles et filtres concernés. Les états historiques garderont leur libellé capturé.':'La catégorie sera disponible dans les fiches de l’inventaire.'}</p><button class="primary wide">Enregistrer la catégorie</button></form>`)}
const actions={
 close:closeSheet,
 more:()=>showSheet('Plus',`<div class="menu-grid">${['wear','wishes','stats','data','settings'].map(k=>`<button data-nav="${k}">${icon(k)}<span>${labels[k]}</span>${icon('arrow')}</button>`).join('')}</div>`),
 theme:()=>commit(d=>d.settings.theme=({auto:'dark',dark:'light',light:'auto'})[d.settings.theme],'Thème enregistré.'),
 'new-item':()=>editItem(), 'new-pack':()=>packEditor(), 'new-list':()=>listEditor(), 'new-wish':()=>wishEditor(),
 filter:filterSheet,
 'clear-filter':()=>{filter={q:'',category:'',location:'',condition:'',kind:'',tags:[],tagMode:'all',unknown:false,includeHidden:false,uncategorized:false};render()},
 customize:()=>{customizing=!customizing;render()},
 'customize-home':()=>{customizing=true;navigate('home')},
 'default-layout':async()=>{if(confirm('Rétablir la disposition par défaut ? Les données de ton inventaire restent conservées.'))await commit(d=>{d.settings.dashboardOrder=[...Gear.moduleIds];d.settings.dashboardSizes={}})},
 'choose-active':chooseActive,
 'new-category':()=>categoryEditor(),
 backup:()=>exportBackup(),
 'csv-export':()=>{download('MY_GEAR_inventaire_'+localDate()+'.csv',Gear.toCSV(state),'text/csv;charset=utf-8');toast('CSV généré. Le JSON complet reste nécessaire pour les photos et les configurations.')},
 'before-export':async()=>{const old=await GearStore.read('before-restore');if(!old)return toast('Aucun état avant restauration n’a encore été conservé.');try{exportBackup(Gear.normalize(old))}catch{download('MY_GEAR_avant_restauration_donnees_brutes.json',JSON.stringify(old,null,2));toast('État brut précédent généré pour récupération.')}},
 'raw-export':async()=>download('MY_GEAR_recuperation_brute_'+localDate()+'.json',JSON.stringify(await GearStore.raw(),null,2)),
 restore:async()=>{if(!pendingRestore)return;if(!confirm('Remplacer tous les modules par cette sauvegarde ? Une copie locale de l’état actuel sera conservée.'))return;const data=pendingRestore;if(await commit(()=>{},'Sauvegarde restaurée.',{restore:true,replace:data})){pendingRestore=null;const check=await GearStore.read();if(Gear.hash(JSON.stringify(check))!==Gear.hash(JSON.stringify(state)))return toast('Restauration écrite, mais relecture différente : conserve les sauvegardes et recharge.');navigate('home');toast('Restauration enregistrée et relue avec succès.')}},
 'provided-csv':async()=>{pendingCSV=null;$('csv-preview').innerHTML='<div class="notice">Lecture du CSV fourni…</div>';const response=await fetch('./inventaire-fourni.csv');if(!response.ok)throw Error('CSV fourni indisponible');try{await csvFromText(await response.text())}catch(e){$('csv-preview').innerHTML=`<div class="notice">Import refusé : ${esc(e.message)}</div>`}},
 'commit-csv':async()=>{if(!pendingCSV)return;const preview=pendingCSV,prefer=$('csv-priority').value;if(!confirm(`Confirmer ${preview.newCount} ajout(s) et ${preview.updateCount} rapprochement(s) ? ${preview.conflicts} conflit(s) utiliseront les valeurs ${prefer==='local'?'locales':'du CSV'}.`))return;if(await commit(d=>Gear.applyCSV(d,preview,prefer),'Inventaire CSV importé, autres modules et photos conservés.')){pendingCSV=null;render()}},
 'cancel-simulation':()=>{simulation=null;render()},
 'save-simulation':()=>{if(!simulation)return;showSheet('Enregistrer la simulation',`<form id="simulation-form" class="fields">${input('Nom de la nouvelle configuration','name','text',(state.packs.find(p=>p.id===simulation.packId)?.name||'Configuration')+' · simulation','required maxlength="160"')}<p class="wide muted">La configuration originale ne sera pas remplacée.</p><button class="primary wide">Créer la configuration</button></form>`)},
 'check-cache':checkOffline,
 persistent:async()=>{const granted=await navigator.storage?.persist?.();toast(granted?'Stockage persistant accordé par le navigateur.':'Le navigateur ne l’a pas accordé. Garde une sauvegarde JSON complète.')},
 install:async()=>{if(!installPrompt)return toast('Utilise le menu du navigateur → Installer l’application / Ajouter à l’écran d’accueil.');await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null},
 'check-update':async()=>{const reg=await navigator.serviceWorker?.getRegistration();if(!reg)return toast('Mises à jour disponibles après une ouverture en HTTPS.');await reg.update();toast(reg.waiting?'Une mise à jour est prête à être activée.':'Recherche effectuée ; le navigateur vérifiera les fichiers de mise à jour.')},
 update:()=>{if(!swWaiting)return;if(confirm('Activer la mise à jour maintenant ? Enregistre et ferme les formulaires avant de continuer.'))swWaiting.postMessage({type:'SKIP_WAITING'})}
};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(busy&&!b.dataset.nav){toast('Enregistrement en cours, patiente un instant.');return}try{
 if(b.dataset.nav)return navigate(b.dataset.nav);
 if(b.dataset.action){await actions[b.dataset.action]?.();return}
 if(b.dataset.item){detailTab='details';return navigate('item',b.dataset.item)}
 if(b.dataset.editItem)return editItem(b.dataset.editItem);
 if(b.dataset.pack)return navigate('pack',b.dataset.pack);
 if(b.dataset.editPack)return packEditor(b.dataset.editPack);
 if(b.dataset.editList)return listEditor(b.dataset.editList);
 if(b.dataset.editWish)return wishEditor(b.dataset.editWish);
 if(b.dataset.renameCategory)return categoryEditor(b.dataset.renameCategory);
 if(b.dataset.inventoryMode){inventoryMode=b.dataset.inventoryMode;render();return}
 if(Object.hasOwn(b.dataset,'category')){filter.category=b.dataset.category;filter.uncategorized=b.dataset.category==='';inventoryMode='items';render();return}
 if(b.dataset.detailTab){detailTab=b.dataset.detailTab;render();return}
 if(b.dataset.packTab){packTab=b.dataset.packTab;render();return}
 if(b.dataset.order){const i=state.settings.dashboardOrder.indexOf(b.dataset.order),j=i+Number(b.dataset.dir);await commit(d=>{[d.settings.dashboardOrder[i],d.settings.dashboardOrder[j]]=[d.settings.dashboardOrder[j],d.settings.dashboardOrder[i]]},'Ordre enregistré.');return}
 if(b.dataset.size){await commit(d=>d.settings.dashboardSizes[b.dataset.size]=({auto:'compact',compact:'wide',wide:'auto'})[d.settings.dashboardSizes[b.dataset.size]||'auto'],'Largeur enregistrée pour grand écran.');return}
 if(b.dataset.setActive){if(await commit(d=>d.settings.activePackId=b.dataset.setActive,'Configuration active enregistrée.'))closeSheet();return}
 if(b.dataset.duplicateItem){let newId;if(await commit(d=>newId=Gear.duplicate(d,b.dataset.duplicateItem),'Copie créée : vérifie la quantité possédée.'))navigate('item',newId);return}
 if(b.dataset.deleteItem){const id=b.dataset.deleteItem,i=Gear.byId(state,id),pc=state.packs.filter(p=>p.entries.some(e=>e.itemId===id)).length,lc=state.lists.filter(l=>l.entries.some(e=>e.itemId===id)).length;if(!confirm(`Supprimer « ${i.name} » ? L’article sera retiré de ${pc} configuration(s) et ${lc} liste(s). Les états historiques resteront conservés.`))return;if(await commit(d=>Gear.removeItem(d,id),'Article supprimé et références actuelles mises à jour.'))navigate('inventory');return}
 if(b.dataset.copyPack){const old=state.packs.find(p=>p.id===b.dataset.copyPack);let id=Gear.uuid();if(await commit(d=>d.packs.push({...Gear.copy(old),id,name:(old.name+' (copie)').slice(0,160),history:[]}),'Configuration dupliquée, sans inventer d’historique.'))navigate('pack',id);return}
 if(b.dataset.deletePack){const id=b.dataset.deletePack,p=state.packs.find(p=>p.id===id);if(!confirm(`Supprimer « ${p.name} » et son historique ? Les listes associées seront conservées comme listes libres.`))return;if(await commit(d=>{d.packs=d.packs.filter(p=>p.id!==id);if(d.settings.activePackId===id)d.settings.activePackId=null;for(const l of d.lists)if(l.packId===id)l.packId=null})){closeSheet();navigate('packs')}return}
 if(b.dataset.createList)return listEditor(null,b.dataset.createList);
 if(b.dataset.startSimulation){const p=state.packs.find(p=>p.id===b.dataset.startSimulation);simulation={packId:p.id,entries:Gear.copy(p.entries)};packTab='content';render();return}
 if(b.dataset.snapshot){await commit(d=>Gear.remember(d,d.packs.find(p=>p.id===b.dataset.snapshot),'État enregistré manuellement'),'État historique enregistré.');return}
 if(b.dataset.exchange){download('MY_GEAR_echange_configuration.json',JSON.stringify(Gear.exchange(state,b.dataset.exchange),null,2));toast('Échange manuel exporté ; aucune synchronisation n’a été lancée.');return}
 if(b.dataset.addEntry)return entryEditor('pack',b.dataset.addEntry);
 if(b.dataset.addListEntry)return entryEditor('list',b.dataset.addListEntry);
 if(b.dataset.removeEntry){await mutateEntries(b.dataset.removeEntry,entries=>{const n=entries.findIndex(e=>e.itemId===b.dataset.removeEntry);if(n>=0)entries.splice(n,1)});return}
 if(b.dataset.removeListEntry){await commit(d=>{const l=d.lists.find(l=>l.id===listId);l.entries=l.entries.filter(e=>e.itemId!==b.dataset.removeListEntry)});return}
 if(b.dataset.syncList){if(confirm('Actualiser les articles et quantités depuis la configuration ? Les quantités déjà préparées seront conservées dans la limite des nouvelles demandes.'))await commit(d=>Gear.syncList(d,d.lists.find(l=>l.id===b.dataset.syncList)));return}
 if(b.dataset.deleteList){if(confirm('Supprimer cette liste et ses états de préparation ?'))await commit(d=>{d.lists=d.lists.filter(l=>l.id!==b.dataset.deleteList);listId=null});return}
 if(b.dataset.acquireWish)return editItem(null,b.dataset.acquireWish);
 if(b.dataset.deleteWish){if(confirm('Supprimer ce souhait ?'))await commit(d=>d.wishes=d.wishes.filter(w=>w.id!==b.dataset.deleteWish));return}
 if(b.dataset.loadFilter){const f=state.savedFilters.find(f=>f.id===b.dataset.loadFilter);filter={...filter,...Gear.copy(f.filter)};inventoryMode='items';navigate('inventory');return}
 if(b.dataset.deleteFilter){if(confirm('Supprimer ces critères sauvegardés ?'))await commit(d=>d.savedFilters=d.savedFilters.filter(f=>f.id!==b.dataset.deleteFilter));return}
 if(b.dataset.tagFilter){filter={q:'',category:'',location:'',condition:'',kind:'',tags:[b.dataset.tagFilter],tagMode:'all',unknown:false,includeHidden:false,uncategorized:false};inventoryMode='items';navigate('inventory');return}
 if(b.dataset.locationFilter){filter={q:'',category:'',location:b.dataset.locationFilter,condition:'',kind:'',tags:[],tagMode:'all',unknown:false,includeHidden:false,uncategorized:false};inventoryMode='items';navigate('inventory');return}
 if(Object.hasOwn(b.dataset,'removePhoto')){photoDraft.splice(Number(b.dataset.removePhoto),1);$('photo-draft').innerHTML=draftPhotos();return}
 if(Object.hasOwn(b.dataset,'viewPhoto')){const i=Gear.byId(state,itemId),p=i.photos[Number(b.dataset.viewPhoto)];showSheet('Photo personnelle',`<img src="${p}" alt="Photo de ${esc(i.name)}" style="width:100%;border-radius:12px">`);return}
 }catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='inventory-search'){const pos=e.target.selectionStart;filter.q=e.target.value;render();$('inventory-search').focus();$('inventory-search').setSelectionRange(pos,pos)}});
document.addEventListener('change',async e=>{const t=e.target;try{
 if(t.id==='theme-select'){await commit(d=>d.settings.theme=t.value);return}
 if(t.id==='trek-only'){await commit(d=>d.settings.hiddenGeneral=t.checked);return}
 if(t.id==='wear-filter'){wearFilter=t.value;render();return}
 if(t.id==='list-select'){listId=t.value;render();return}
 if(t.id==='compare-a'||t.id==='compare-b'){compareIds=[$('compare-a').value,$('compare-b').value];render();return}
 if(t.dataset.categoryVisible){await commit(d=>d.categories.find(c=>c.id===t.dataset.categoryVisible).hidden=!t.checked);return}
 if(t.dataset.entryQty){const q=Number(t.value);if(!Number.isInteger(q)||q<1)throw Error('Quantité entière supérieure à zéro attendue');await mutateEntries(t.dataset.entryQty,entries=>entries.find(e=>e.itemId===t.dataset.entryQty).qty=q);return}
 if(t.dataset.entryKind){await mutateEntries(t.dataset.entryKind,entries=>entries.find(e=>e.itemId===t.dataset.entryKind).kind=t.value);return}
 if(t.dataset.readyAll){const id=t.dataset.readyAll,checked=t.checked;await commit(d=>{const l=d.lists.find(l=>l.id===listId),x=l.entries.find(e=>e.itemId===id);x.readyQty=checked?Math.min(x.qty,Gear.byId(d,id).qty):0;x.checked=x.readyQty===x.qty});return}
 if(t.dataset.readyQty){const id=t.dataset.readyQty,q=Number(t.value);await commit(d=>{const l=d.lists.find(l=>l.id===listId),x=l.entries.find(e=>e.itemId===id);if(!Number.isInteger(q)||q<0||q>x.qty)throw Error('Quantité préparée comprise entre 0 et la demande attendue');x.readyQty=q;x.checked=Math.min(q,Gear.byId(d,id).qty)===x.qty});return}
 if(t.dataset.listQty){const id=t.dataset.listQty,q=Number(t.value);await commit(d=>{const l=d.lists.find(l=>l.id===listId),x=l.entries.find(e=>e.itemId===id);if(!Number.isInteger(q)||q<1)throw Error('Quantité demandée entière supérieure à zéro attendue');x.qty=q;x.readyQty=Math.min(x.readyQty,q);x.checked=Math.min(x.readyQty,Gear.byId(d,id).qty)===q});return}
 if(t.id==='weight-unit'){const form=$('item-form'),old=form.dataset.unit||'g',field=form.elements.namedItem('weight'),v=num(field.value);if(v!==null&&old!==t.value)field.value=old==='g'?String(v/1000):String(v*1000);form.dataset.unit=t.value;field.step=t.value==='kg'?'0.0001':'0.1';return}
 if(t.id==='restore-input'&&t.files[0]){pendingRestore=null;const el=$('restore-preview');try{pendingRestore=await readJSON(t.files[0]);el.innerHTML=restorePreview()}catch(err){el.innerHTML=`<div class="notice">Restauration refusée : ${esc(err.message)}</div>`}return}
 if(t.id==='csv-input'&&t.files[0]){pendingCSV=null;try{if(t.files[0].size>16e6)throw Error('CSV supérieur à 16 Mo');await csvFromText(await t.files[0].text())}catch(err){$('csv-preview').innerHTML=`<div class="notice">Import refusé : ${esc(err.message)}</div>`}return}
 if(t.id==='item-photos'&&t.files.length){const owner=$('item-form');const files=[...t.files];if(photoDraft.length+files.length>4)throw Error('Quatre photos maximum par article');t.disabled=true;try{for(const file of files){if(file.size>15e6)throw Error('Une photo dépasse 15 Mo');const image=await createImageBitmap(file);try{const scale=Math.min(1,1024/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);if($('item-form')!==owner||!$('sheet').open)return;photoDraft.push(canvas.toDataURL('image/jpeg',.78));$('photo-draft').innerHTML=draftPhotos()}finally{image.close()}}}finally{if(t.isConnected)t.disabled=false}return}
 }catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{const form=e.target,id=form.getAttribute('id');if(!['item-form','pack-form','list-form','wish-form','entry-form','filter-form','category-form','simulation-form'].includes(id))return;e.preventDefault();if(busy)return;const fd=new FormData(form),data=Object.fromEntries(fd),name=String(data.name||'').trim();let success=false;try{
 if(id==='item-form'){const old=Gear.byId(state,editingItemId),w=num(data.weight);const item={...old,id:editingItemId||Gear.uuid(),name,brand:String(data.brand||'').trim(),model:String(data.model||'').trim(),category:String(data.category||'').trim(),qty:num(data.qty),weight:w===null?null:w*(data.weightUnit==='kg'?1000:1),kind:data.kind,condition:data.condition,location:String(data.location||'').trim(),tags:[...new Set(String(data.tags||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean))],wear:num(data.wear),wearLimit:num(data.wearLimit),notes:String(data.notes||''),dimensions:String(data.dimensions||'').trim(),capacity:String(data.capacity||'').trim(),price:num(data.price),photo:photoDraft[0]||null,photos:photoDraft.slice(1)};const wish=acquiringWishId;success=await commit(d=>{if(wish&&!d.wishes.some(w=>w.id===wish))throw Error('Souhait déjà acquis ou supprimé');Gear.updateItem(d,item);if(wish)d.wishes=d.wishes.filter(w=>w.id!==wish)},wish?'Acquisition enregistrée et souhait retiré.':'Équipement enregistré.');if(success){closeSheet();navigate('item',item.id)}return}
 if(id==='pack-form'){const pId=form.dataset.packId||Gear.uuid();success=await commit(d=>{const old=d.packs.find(p=>p.id===pId),days=num(data.days);if(days!==null&&(!Number.isInteger(days)||days<1||days>3650))throw Error('Durée entière entre 1 et 3650 jours attendue');const pack={...old,id:pId,name,activity:String(data.activity||'').trim(),days,notes:String(data.notes||''),entries:old?.entries||[],history:old?.history||[]};if(old)Object.assign(old,pack);else{d.packs.push(pack);if(!d.settings.activePackId)d.settings.activePackId=pId}});if(success){closeSheet();navigate('pack',pId)}return}
 if(id==='list-form'){const lId=form.dataset.listId||Gear.uuid();success=await commit(d=>{const old=d.lists.find(l=>l.id===lId),linked=data.packId||null;if(old){old.name=name;old.packId=linked}else{const pack=d.packs.find(p=>p.id===linked);d.lists.push({id:lId,name,packId:linked,entries:pack?pack.entries.map(e=>({itemId:e.itemId,qty:e.qty,readyQty:0,checked:false})):[]})}});if(success){listId=lId;closeSheet();navigate('prep')}return}
 if(id==='wish-form'){const wId=form.dataset.wishId||Gear.uuid();success=await commit(d=>{const old=d.wishes.find(w=>w.id===wId),w={...old,id:wId,name,priority:data.priority,price:num(data.price),notes:String(data.notes||''),replacementFor:data.replacementFor||null};if(old)Object.assign(old,w);else d.wishes.push(w)});}
 if(id==='entry-form'){const target=form.dataset.targetId,itemId=data.itemId,q=num(data.qty);if(!Number.isInteger(q)||q<1)throw Error('Quantité entière supérieure à zéro attendue');if(form.dataset.type==='pack'){const p=state.packs.find(p=>p.id===target),entries=Gear.copy(simulation?.packId===p.id?simulation.entries:p.entries),entry=entries.find(e=>e.itemId===itemId);if(entry)entry.qty+=q;else entries.push({itemId,qty:q});if(simulation?.packId===p.id){const test=Gear.copy(state);test.packs.find(x=>x.id===p.id).entries=entries;Gear.validate(test);simulation.entries=entries;success=true;render()}else success=await commit(d=>Gear.updateEntries(d,p.id,entries))}else success=await commit(d=>{const l=d.lists.find(l=>l.id===target),old=l.entries.find(e=>e.itemId===itemId);if(old){old.qty+=q;old.checked=old.readyQty===old.qty}else l.entries.push({itemId,qty:q,readyQty:0,checked:false})});}
 if(id==='filter-form'){const f={q:String(data.q||''),category:data.category==='__none__'?'':data.category,uncategorized:data.category==='__none__',location:data.location,condition:data.condition,kind:data.kind,tags:fd.getAll('tag'),tagMode:data.tagMode,unknown:fd.has('unknown'),includeHidden:fd.has('includeHidden')};if(String(data.saveName||'').trim())success=await commit(d=>d.savedFilters.push({id:Gear.uuid(),name:String(data.saveName).trim(),filter:Gear.copy(f)}),'Critères sauvegardés.');else success=true;if(success){filter=f;inventoryMode='items';closeSheet();navigate('inventory')}return}
 if(id==='category-form'){success=await commit(d=>{if(form.dataset.categoryId)Gear.renameCategory(d,form.dataset.categoryId,name);else{if(d.categories.some(c=>Gear.norm(c.name)===Gear.norm(name)))throw Error('Cette catégorie existe déjà');d.categories.push({id:Gear.uuid(),name,hidden:false})}});}
 if(id==='simulation-form'){if(!simulation)throw Error('Simulation absente');const sim=Gear.copy(simulation),orig=state.packs.find(p=>p.id===sim.packId),newId=Gear.uuid();success=await commit(d=>d.packs.push({...Gear.copy(orig),id:newId,name,entries:sim.entries,history:[]}),'Simulation enregistrée comme configuration distincte.');if(success){simulation=null;closeSheet();navigate('pack',newId)}return}
 if(success)closeSheet();
 }catch(err){toast(err.message)}});
window.addEventListener('hashchange',()=>{parseRoute();render()});
window.addEventListener('online',shell);window.addEventListener('offline',shell);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
