async function checkOffline(){const el=$('offline-status');try{if(!navigator.serviceWorker){if(el)el.textContent='HTTPS requis';return}const reg=await navigator.serviceWorker.getRegistration();if(!reg?.active){if(el)el.textContent='Première mise en cache en cours';return}const channel=new MessageChannel();const result=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Réponse du cache indisponible')),4000);channel.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data)};reg.active.postMessage({type:'CHECK_CACHE'},[channel.port2])});const current=$('offline-status');if(current){current.textContent=result.missing.length?result.missing.length+' ressource(s) absente(s)':'Cache complet · '+result.count+' ressources';current.classList.toggle('ready',!result.missing.length)}return result}catch(err){if(el)el.textContent=err.message}}
async function initSW(){if(!('serviceWorker'in navigator)||location.protocol==='file:')return;try{const reg=await navigator.serviceWorker.register('./sw.js');const waiting=()=>{if(reg.waiting){swWaiting=reg.waiting;shell()}};waiting();reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'){waiting();checkOffline()}})});let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{checkOffline();if(swWaiting&&!reloading){reloading=true;location.reload()}})}catch(err){toast('Cache hors ligne non initialisé : '+err.message)}}
async function init(){parseRoute();render();try{const result=await GearStore.load();state=result.data;loaded=true;render();if(result.migrated)toast('Données MY GEAR v1 reprises ; ancienne clé conservée.')}catch(err){blocked=err.message;loaded=true;render()}initSW()}
init();
